// TestClient_ReadOnlyGuard_GETControl proves the absolute method guard stays
// narrowly scoped: GET reaches the transport in ordinary and verify modes.
func TestClient_ReadOnlyGuard_GETControl(t *testing.T) {
	envModes := []struct {
		name     string
		verify   string
		liveHTTP string
	}{
		{name: "no-env"},
		{name: "verify", verify: "1"},
		{name: "verify-live-http", verify: "1", liveHTTP: "1"},
	}

	for _, envMode := range envModes {
		envMode := envMode
		t.Run(envMode.name, func(t *testing.T) {
			t.Setenv("PRINTING_PRESS_VERIFY", envMode.verify)
			t.Setenv("PRINTING_PRESS_VERIFY_LIVE_HTTP", envMode.liveHTTP)
			c, rec := newClientWithRecorder(t)

			body, status, err := c.do(context.Background(), http.MethodGet, "/test", nil, nil, nil)
			if err != nil {
				t.Fatalf("GET returned error: %v", err)
			}
			if status != http.StatusOK {
				t.Fatalf("GET status = %d, want %d", status, http.StatusOK)
			}
			if string(body) != "{}" {
				t.Fatalf("GET body = %q, want %q", body, "{}")
			}
			if rec.calls != 1 {
				t.Fatalf("GET attempted %d HTTP calls; want 1", rec.calls)
			}
		})
	}
}
